-- EXPLAIN ANALYZE of UPDATE ... FROM and DELETE ... USING into a
-- partitioned table or an inheritance tree counts each member's scan
-- under the Append and the join over it, as for a plain target, in every
-- format; VERBOSE shows the same lists EXPLAIN does. VACUUM after each
-- rolled-back write keeps PostgreSQL's heap at its analyzed size. The rows
-- stay under the forced-spill run's 256 KiB memtable.
CREATE TABLE p671 (id int, v int) PARTITION BY RANGE (id);
CREATE TABLE p671_1 PARTITION OF p671 FOR VALUES FROM (0) TO (300);
CREATE TABLE p671_2 PARTITION OF p671 FOR VALUES FROM (300) TO (2000);
INSERT INTO p671 SELECT g, g FROM generate_series(1, 450) g;
CREATE TABLE s671 (k int, w int);
INSERT INTO s671 SELECT (g % 20) * 7, g FROM generate_series(1, 40) g;
CREATE TABLE b671 (k int, w int);
INSERT INTO b671 SELECT g % 500, g FROM generate_series(1, 800) g;
CREATE TABLE i671 (a int, v int);
CREATE TABLE i671_c (CHECK (a < 10)) INHERITS (i671);
INSERT INTO i671 SELECT g, g FROM generate_series(10, 200) g;
INSERT INTO i671_c SELECT g, g FROM generate_series(1, 9) g;
CREATE TABLE t671 (id int, v int, x text);
INSERT INTO t671 SELECT g, g, 'x' || g FROM generate_series(1, 400) g;
ANALYZE p671;
ANALYZE s671;
ANALYZE b671;
ANALYZE i671;
ANALYZE i671_c;
ANALYZE t671;
\set e 'EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)'
BEGIN; :e UPDATE p671 SET v = s671.w FROM s671 WHERE p671.id = s671.k; ROLLBACK; VACUUM p671;
BEGIN; :e UPDATE p671 SET v = b671.w FROM b671 WHERE p671.id = b671.k; ROLLBACK; VACUUM p671;
BEGIN; :e UPDATE p671 SET v = s671.w FROM s671 WHERE p671.id = s671.k AND p671.id < 100; ROLLBACK; VACUUM p671;
BEGIN; :e DELETE FROM p671 USING s671 WHERE p671.v < s671.k AND p671.id < 20; ROLLBACK; VACUUM p671;
BEGIN; :e UPDATE i671 SET v = s671.w FROM s671 WHERE i671.a = s671.k; ROLLBACK; VACUUM i671;
BEGIN; :e UPDATE ONLY i671 SET v = s671.w FROM s671 WHERE i671.a = s671.k; ROLLBACK; VACUUM i671;
BEGIN; EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF, VERBOSE)
  UPDATE t671 SET v = s671.w, x = t671.x || 'y' FROM s671
  WHERE t671.id = s671.k AND t671.v + s671.w > 30 RETURNING t671.id, s671.*; ROLLBACK; VACUUM t671;
BEGIN; EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF, VERBOSE)
  UPDATE p671 SET v = b671.w FROM b671 WHERE p671.id = b671.k AND b671.w < 600; ROLLBACK; VACUUM p671;
BEGIN; EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF, VERBOSE)
  DELETE FROM t671 USING s671 WHERE t671.v < s671.k AND t671.id < 8; ROLLBACK; VACUUM t671;
BEGIN; EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF, FORMAT JSON)
  DELETE FROM p671 USING s671 WHERE p671.id = s671.k; ROLLBACK; VACUUM p671;
BEGIN; EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF, FORMAT YAML)
  UPDATE t671 SET v = 1 FROM s671 WHERE t671.v < s671.k AND t671.id < 5; ROLLBACK; VACUUM t671;
BEGIN; EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF, FORMAT XML)
  UPDATE p671 SET v = s671.w FROM s671 WHERE p671.id = s671.k AND p671.id > 250; ROLLBACK; VACUUM p671;
EXPLAIN (COSTS OFF) UPDATE p671 SET v = b671.w FROM b671 WHERE p671.id = b671.k;
EXPLAIN (COSTS OFF) UPDATE t671 SET v = s671.w FROM s671 WHERE t671.v < s671.k AND t671.id < 3;
UPDATE p671 SET v = b671.w FROM b671 WHERE p671.id = b671.k AND p671.id < 8 RETURNING p671.*, b671.*;
UPDATE p671 SET id = id + 300, v = s671.w FROM s671
  WHERE p671.id = s671.k AND p671.id < 60 RETURNING p671.tableoid::regclass, p671.*, s671.w;
DELETE FROM i671 USING s671 WHERE i671.a = s671.k RETURNING i671.tableoid::regclass, i671.*, s671.w;
SELECT tableoid::regclass, * FROM p671 WHERE v <> id ORDER BY id;
SELECT * FROM i671 ORDER BY a LIMIT 5;
